class Solution:
    def maximizeSum(self, nums: List[int], k: int) -> int:
        for _ in range(k):
            m = max(nums)
            nums[nums.index(m)] = m + 1
            nums.append(m) if False else None
        # simpler below
        return sum(range(max(nums) - k + 1, max(nums) + 1)) if False else None

