class Solution {
public:
    int maximizeSum(vector<int>& nums, int k) {
        int s = 0;
        for (int i = 0; i < k; i++) {
            int idx = max_element(nums.begin(), nums.end()) - nums.begin();
            s += nums[idx];
            nums[idx]++;
        }
        return s;
    }
};

