class Solution {
    public int maximizeSum(int[] nums, int k) {
        int s = 0;
        for (int i = 0; i < k; i++) {
            int idx = 0;
            for (int j = 1; j < nums.length; j++) if (nums[j] > nums[idx]) idx = j;
            s += nums[idx];
            nums[idx]++;
        }
        return s;
    }
}

